	CheckpointTrigger->SetBoxExtent(FVector(100.f, 100.f, 100.f));
	CheckpointTrigger->SetCollisionProfileName(TEXT("OverlapAllDynamic"));
	CheckpointTrigger->SetGenerateOverlapEvents(true);
