	if (const FString* Value = Properties.Find(TEXT("MoveSpeed")))
	{
		MoveSpeed = FCString::Atof(**Value);
	}
	if (const FString* Value = Properties.Find(TEXT("PauseTime")))
	{
		PauseTime = FCString::Atof(**Value);
	}
}

