    10→UWjWorldGameplayAbilityBase::UWjWorldGameplayAbilityBase()
    11→{
    12→	// 제거 상태에서는 어빌리티 활성화 차단
    13→	ActivationBlockedTags.AddTag(WjWorldGameplayTag::State_Eliminated());
