    15→
    16→bool UWjWorldGameplayAbilityBase::CanActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayTagContainer* SourceTags, const FGameplayTagContainer* TargetTags, OUT FGameplayTagContainer* OptionalRelevantTags) const
    17→{
    18→	if (!Super::CanActivateAbility(Handle, ActorInfo, SourceTags, TargetTags, OptionalRelevantTags))
    19→	{
    20→		return false;
    21→	}
    22→
    23→	// GameStatePlay 기반 체크 (GamePhase + AllowedAbilityTags)
    24→	if (ActorInfo && ActorInfo->AvatarActor.IsValid())
    25→	{
    26→		UWorld* World = ActorInfo->AvatarActor->GetWorld();
    27→		if (World)
    28→		{
    29→			AWjWorldGameStatePlay* GameState = World->GetGameState<AWjWorldGameStatePlay>();
    30→			if (GameState)
    31→			{
    32→				// 게임 시작 전/후에는 어빌리티 사용 금지 (Playing 상태에서만 허용)
    33→				if (GameState->GetGamePhase() != EGamePhase::Playing)
    34→				{
    35→					return false;
    36→				}
    37→
    38→				// AllowedAbilityTags 체크 (빈 컨테이너 = 전부 허용, 하위 호환)
    39→				const FGameplayTagContainer& AllowedTags = GameState->GetAllowedAbilityTags();
    40→				if (AllowedTags.Num() > 0)
    41→				{
    42→					// 이 어빌리티의 AssetTag가 AllowedTags에 포함되어야 활성화
    43→					const FGameplayTagContainer& AssetTags = GetAssetTags();
    44→					if (!AllowedTags.HasAny(AssetTags))
    45→					{
    46→						return false;
    47→					}
    48→				}
    49→			}
    50→		}
    51→	}
    52→
    53→	return true;
    54→}
