    56→void UWjWorldGameplayAbilityBase::ApplyCooldown(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo) const
    57→{
    58→	if (CooldownDuration <= 0.f || CooldownTags.Num() == 0)
    59→	{
    60→		return;
    61→	}
    62→
    63→	UGameplayEffect* CooldownGE = GetCooldownGameplayEffect();
    64→	if (!CooldownGE)
    65→	{
    66→		// GE_AbilityCooldown CDO 사용
    67→		CooldownGE = UGE_AbilityCooldown::StaticClass()->GetDefaultObject<UGameplayEffect>();
    68→	}
    69→
    70→	if (CooldownGE)
    71→	{
    72→		FGameplayEffectSpecHandle SpecHandle = MakeOutgoingGameplayEffectSpec(CooldownGE->GetClass(), GetAbilityLevel());
    73→		if (SpecHandle.IsValid())
    74→		{
    75→			// SetByCaller로 Duration 설정
    76→			SpecHandle.Data->SetSetByCallerMagnitude(WjWorldGameplayTag::Data_Cooldown(), CooldownDuration);
    77→
    78→			// 쿨다운 태그를 DynamicGrantedTags에 추가
    79→			SpecHandle.Data->DynamicGrantedTags.AppendTags(CooldownTags);
    80→
    81→			ApplyGameplayEffectSpecToOwner(Handle, ActorInfo, ActivationInfo, SpecHandle);
    82→		}
    83→	}
    84→}
    85→
    86→const FGameplayTagContainer* UWjWorldGameplayAbilityBase::GetCooldownTags() const
    87→{
    88→	// 부모 태그와 CooldownTags 합산
    89→	MergedCooldownTags.Reset();
    90→
    91→	const FGameplayTagContainer* ParentTags = Super::GetCooldownTags();
    92→	if (ParentTags)
    93→	{
    94→		MergedCooldownTags.AppendTags(*ParentTags);
    95→	}
    96→
    97→	MergedCooldownTags.AppendTags(CooldownTags);
    98→
    99→	return &MergedCooldownTags;
   100→}
