    32→void UGA_Dash::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* TriggerEventData)
    33→{
    34→	Super::ActivateAbility(Handle, ActorInfo, ActivationInfo, TriggerEventData);
    35→
    36→	// EndAbility 호출용 캐시
    37→	CachedHandle = Handle;
    38→	CachedActorInfo = ActorInfo;
    39→	CachedActivationInfo = ActivationInfo;
    40→
    41→	if (HasAuthorityOrPredictionKey(ActorInfo, &ActivationInfo))
    42→	{
    43→		if (!CommitAbility(Handle, ActorInfo, ActivationInfo))
    44→		{
    45→			EndAbility(Handle, ActorInfo, ActivationInfo, true, true);
    46→			return;
    47→		}
    48→
    49→		ACharacter* Character = Cast<ACharacter>(ActorInfo->AvatarActor.Get());
    50→		if (!Character)
    51→		{
    52→			EndAbility(Handle, ActorInfo, ActivationInfo, true, true);
    53→			return;
    54→		}
    55→
    56→		// 전방으로 대시 (LaunchCharacter)
    57→		FVector ForwardDir = Character->GetActorForwardVector();
    58→		FVector LaunchVelocity = ForwardDir * (DashDistance / DashDuration);
