    64→		// 대시 종료 타이머
    65→		if (UWorld* World = GetWorld())
    66→		{
    67→			World->GetTimerManager().SetTimer(DashTimerHandle, this, &UGA_Dash::OnDashEnd, DashDuration, false);
    68→		}
    69→	}
    70→}
