### **2. SIMPLE ABILITY EXAMPLE: GA_Jump**
**Files:** `/Source/WjWorld/AbilitySystem/Abilities/GA_Jump.h/cpp`

**Pattern - Immediate Execution Ability:**
```cpp
// Constructor setup
UGA_Jump::UGA_Jump()
{
    InstancingPolicy = EGameplayAbilityInstancingPolicy::InstancedPerActor;
    NetExecutionPolicy = EGameplayAbilityNetExecutionPolicy::LocalPredicted;

    FGameplayTagContainer AssetTags;
    AssetTags.AddTag(WjWorldGameplayTag::Ability_Jump());
    SetAssetTags(AssetTags);

    // Blocked by other states
    ActivationBlockedTags.AddTag(WjWorldGameplayTag::State_SpawnBrickPreview());
    ActivationBlockedTags.AddTag(WjWorldGameplayTag::State_LiftBrickCarry());

    // Cooldown setup
    CooldownTags.AddTag(WjWorldGameplayTag::Cooldown_Jump());

    AbilityName = NSLOCTEXT("Abilities", "Jump", "점프");
}

// CanActivateAbility override for custom validation
bool UGA_Jump::CanActivateAbility(...) const
{
    if (!Super::CanActivateAbility(...)) return false;

    const ACharacter* Character = CastChecked<ACharacter>(ActorInfo->AvatarActor.Get());
    return Character && Character->CanJump();
}

// Main ability execution
void UGA_Jump::ActivateAbility(...)
{
    Super::ActivateAbility(...);

    if (HasAuthorityOrPredictionKey(ActorInfo, &ActivationInfo))
    {
        if (!CommitAbility(Handle, ActorInfo, ActivationInfo))
        {
            EndAbility(Handle, ActorInfo, ActivationInfo, true, true);
            return;
        }

        ACharacter* Character = CastChecked<ACharacter>(ActorInfo->AvatarActor.Get());
        Character->Jump();
    }
}

// Input release handling
void UGA_Jump::InputReleased(...)
{
    ACharacter* Character = CastChecked<ACharacter>(ActorInfo->AvatarActor.Get());
    Character->StopJumping();
    EndAbility(Handle, ActorInfo, ActivationInfo, true, false);
}
```

**Key Points:**
- Simple, stateless ability - no preview or complex state management
- Uses `CanActivateAbility()` for validation beyond base checks
- Handles both input press and release
- Uses `CommitAbility()` before executing effect
- Calls `EndAbility()` when complete

