        AbilitySystemComponent->GiveAbility(Spec);
    }
}
```

---

### **7. COMPLEX ABILITY EXAMPLE: GA_SpawnBrick (Preview Pattern)**

**Key Pattern for Stateful Abilities:**

```cpp
// Constructor with activation states
UGA_SpawnBrick::UGA_SpawnBrick()
{
    InstancingPolicy = EGameplayAbilityInstancingPolicy::InstancedPerActor;
    NetExecutionPolicy = EGameplayAbilityNetExecutionPolicy::LocalPredicted;

    FGameplayTagContainer AssetTags;
    AssetTags.AddTag(WjWorldGameplayTag::Ability_SpawnBrick());
    SetAssetTags(AssetTags);

    // This state is applied while ability is active (prevents other abilities)
    ActivationOwnedTags.AddTag(WjWorldGameplayTag::State_SpawnBrickPreview());

    // These abilities are blocked while this is active
    BlockAbilitiesWithTag.AddTag(WjWorldGameplayTag::Ability_NormalAttack());

    CooldownTags.AddTag(WjWorldGameplayTag::Cooldown_SpawnBrick());

    AbilityName = NSLOCTEXT("Abilities", "SpawnBrick", "벽돌 배치");
}

// Charge system interface
virtual bool IsChargeBased() const override { return true; }
virtual int32 GetCurrentCharges() const override;
virtual int32 GetMaxCharges() const override;
virtual float GetChargeRefillTimeRemaining() const override;

// Ability lifecycle
virtual void OnGiveAbility(const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilitySpec& Spec) override;
virtual void OnRemoveAbility(const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilitySpec& Spec) override;
virtual bool CanActivateAbility(...) const override;
virtual void ActivateAbility(...) override;
virtual void EndAbility(...) override;

// Preview system with Confirm/Cancel support
void SpawnPreviewActor();
void DestroyPreviewActor();
void UpdatePreviewLocation();
void OnConfirmCallback();
void OnCancelCallback();
```

